/// <summary>
/// Tự động tải dữ liệu kế hoạch khảo sát nếu có phù hợp từng đối tượng: chưa login, sv, hoặc gv, nhân viên login ...
/// </summary>
private bool TryLoadPollPlan()
{
    string strUsername = User != null ? User.UserName : null;

    PollObject.POL_Plan obj = new PollObject.POL_Plan();
    DataTable dtbPlan = obj.GetDataTable("POL_Plan_SearchForDo", "@LoginName", strUsername);
    if (dtbPlan != null && dtbPlan.Rows.Count > 0)
    {
        DataRow drw = dtbPlan.Rows[0];
        string strTemplate = "<div class='poll-popup'> "
                             + "    <div class='poll-popup-content'>{0}</div> "                                     
                             + "</div>";


        // gán vào control
        spanTitle.InnerHtml = drw["PlanName"].ToString();
        strBody = string.Format(strTemplate, drw["PlanContent"]);

        // link thực hiện hoặc bỏ qua  
        btnNext.OnClientClick = string.Format("window.top.location='/khaosat.aspx?pid={0}'; return false;", WebGlobal.EncodeRequest(drw["PlanID"].ToString())); // link mở form thực hiện khảo sát                
        divCommand.Visible = true;

        // hiển thị
        ShowPopup();
        return true;
    }

    return false;
}

