public void ShowPopup()
{
    // Bootstrap 5: khong dung jQuery .modal('show')
    string strScript = "var _elPopup = document.getElementById('myModal_" + this.ClientID + "');"
        + " if (_elPopup && window.bootstrap && bootstrap.Modal) { bootstrap.Modal.getOrCreateInstance(_elPopup).show(); }";
    ScriptManager.RegisterStartupScript(Page, Page.GetType(), "_ShowPopup" + this.ClientID, strScript, true);
}

